/* --- sites: RVHOOK offsets in the flight loop (rvhook.asm) --- */
#define RV_SITE_mainLoopTop            0x0400  /* interrupts on, no live registers but SI DI BP */
#define RV_SITE_statusCheckAfterKeys   0x0440  /* just before `cmp missionStatus,0 / jne exit` */
#define RV_SITE_statusSetByExitKey     0x0438  /*  */
#define RV_SITE_statusCheckAfterFrame  0x0480  /*  */
#define RV_SITE_skipOrchestra          0x0500  /* a 5-byte `call far`; the layer may step over it */
#define RV_SITE_afterStartup           0x0510  /*  */
#define RV_SITE_afterHangarMission     0x0520  /*  */
#define RV_SITE_autopilotKey           0x0540  /* a 5-byte `call far` the layer steps over on clients */
#define RV_SITE_cockpitPointer         0x0560  /* a 4-byte `call far [mem]`, caller cleans up */
#define RV_SITE_autoAnimationBody      0x0580  /* after autoAnimation's `push bp / mov bp,sp` */

